import {esc,icon} from './ui.mjs';
import {withStableView} from './view-stability.mjs';
import {exportGeneratedFile} from './artifact-export.mjs';
import {aigcReportHtml} from './aigc-report.mjs';
import {importWorkspaceDocument} from './document-import.mjs';
import {createDocumentServiceClient,watchDocumentService} from './document-services-client.mjs';
import {AIGC_NOTICE,aigcLimits,validateAigcText,aigcLabel,aigcPublicError,normalizeAigcResult} from './aigc-detection-model.mjs';
export function ensureAigcStyle(doc=document){if(doc.querySelector('[data-aigc-detection-style]'))return;const link=doc.createElement('link');link.rel='stylesheet';link.href='/workspace/aigc-detection.css';link.dataset.aigcDetectionStyle='';doc.head.append(link);}
const publicError=message=>Object.assign(Error(message),{publicMessage:message});
export function mountAigcDetection({container,fetchImpl,uuid=()=>crypto.randomUUID(),pollInterval=2200,importDocument=importWorkspaceDocument,exportFile=exportGeneratedFile}={}){
 const doc=container.ownerDocument,win=doc.defaultView,$=selector=>container.querySelector(selector);let alive=true,ownerId=null,cap={},busy=false,blocked=false,importing=false,item=null,intent=null,resultText='',recent=[],timer=null,unwatch=()=>{},preview=null;const current=()=>alive&&container.isConnected,client=createDocumentServiceClient({fetchImpl,isCurrent:current});
 ensureAigcStyle(doc);
 function stop(){if(timer!==null)win.clearTimeout(timer);timer=null;}
 function closePreview(){if(!preview)return;const frame=preview.querySelector('iframe');if(frame)frame.srcdoc='';preview.remove();preview=null;}
 function dispose(){if(!alive)return;alive=false;stop();closePreview();client.dispose();unwatch();}
 unwatch=watchDocumentService(container,dispose);
 const status=(message,error=false)=>{const node=$('[data-aigc-status]');if(node){node.textContent=message;node.classList.toggle('is-error',error);node.setAttribute('role',error?'alert':'status');}};
 function persist(){if(!ownerId||!item)return;try{win.localStorage.setItem('paperknow-aigc-last:'+ownerId,JSON.stringify({itemId:item.id}));}catch{status('结果已保存在账户，但本机恢复记录未能保存；请使用最近鉴别查看。',true);}}
 function updateControls(){if(!$('[data-aigc-text]'))return;const locked=busy||importing||blocked||item?.status==='running'||Boolean(intent);$('[data-aigc-text]').disabled=locked;$('[data-aigc-file]').disabled=locked;$('[data-aigc-consent]').disabled=locked;$('[data-aigc-start]').disabled=locked||!cap.ready||!$('[data-aigc-consent]').checked||!$('[data-aigc-text]').value.trim();$('[data-aigc-refresh]').hidden=!item;$('[data-aigc-refresh]').disabled=busy||importing||blocked;$('[data-aigc-retry]').hidden=!intent||Boolean(item);$('[data-aigc-retry]').disabled=busy||blocked;container.querySelectorAll('[data-aigc-report-download],[data-aigc-report-preview]').forEach(node=>node.disabled=busy||importing||blocked||!item?.fullyCompleted);if(preview)preview.querySelectorAll('[data-aigc-preview-print],[data-aigc-preview-download]').forEach(node=>node.disabled=busy||importing||blocked);container.setAttribute('aria-busy',String(busy||importing));container.querySelectorAll('[data-aigc-recent-id]').forEach(node=>node.disabled=busy||importing||blocked||Boolean(intent));}
 function countInput(){const raw=$('[data-aigc-text]').value,limits=aigcLimits(cap),characters=Array.from(raw).length;let parts=0;try{parts=validateAigcText(raw,cap).partCount;}catch{}$('[data-aigc-counter]').textContent=`${characters.toLocaleString('en-US')} / ${limits.maxCharacters.toLocaleString('en-US')} 字符`;$('[data-aigc-parts]').textContent=`本次预计 ${parts} 个片段；每段最多 ${limits.maxPartCharacters.toLocaleString('en-US')} 字符`;updateControls();}
 function renderRecent(){const node=$('[data-aigc-recent]');if(!node)return;node.innerHTML=`<h3>最近鉴别</h3>${recent.length?recent.slice(0,10).map(row=>`<button type="button" data-aigc-recent-id="${esc(row.id)}">${({running:'处理中',completed:'查看分段结果',failed:'处理未完成'})[row.status]} · ${row.characters.toLocaleString('en-US')} 字符</button>`).join(''):'<p>提交后，账户任务会显示在这里。</p>'}`;node.querySelectorAll('[data-aigc-recent-id]').forEach(button=>button.onclick=()=>void command(async()=>{intent=null;resultText='';await read(button.dataset.aigcRecentId);}));updateControls();}
 function renderResult(){if(!current())return;const target=$('[data-aigc-result]');if(!item){target.hidden=true;return;}withStableView(container.closest('.dashboard')||container,()=>{target.hidden=false;const running=item.status==='running',failed=item.status==='failed',uncertain=item.verdict==='undetermined',title=running?'正在鉴别文本':failed?'本次鉴别未完成':uncertain?'分段处理结束，结果仍待核对':'分段鉴别结果';target.innerHTML=`<div class="aigc-detection-result-head"><h3>${title}</h3><span>${item.completedParts} / ${item.partCount} 个片段已处理</span></div>${running?'<p>任务已保存到当前账户，可稍后回来读取，不需要重复提交。</p>':failed?'<p>已保留处理记录。请稍后再试；下方只展示实际收到的分段结果。</p>':`<p class="aigc-detection-verdict ${uncertain?'is-uncertain':''}">${esc(aigcLabel(item.verdict))}</p><p>以下为逐段标签与该标签的置信分，不计算全篇 AI 率。</p>`}<div class="aigc-detection-counts"><div><strong>${item.counts.aigc}</strong>偏 AI 表达片段</div><div><strong>${item.counts.ugc}</strong>偏人工表达片段</div><div><strong>${item.counts.undetermined}</strong>尚不能判定片段</div></div>${item.parts.length?`<div class="aigc-detection-table-wrap" data-scroll-key="aigc-parts"><table class="aigc-detection-table"><thead><tr><th>原文片段</th><th>表达倾向</th><th>标签置信分</th></tr></thead><tbody>${item.parts.map((part,index)=>`<tr><td>第 ${index+1} 段 · 字符 ${part.start+1}–${part.end}${resultText&&part.end>part.start?`<details><summary>查看本次提交的原文</summary><pre>${esc(Array.from(resultText).slice(part.start,part.end).join(''))}</pre></details>`:''}</td><td>${esc(aigcLabel(part.label))}</td><td>${part.confidence===null?'—':`${Number(part.confidence.toFixed(2))} / 100`}</td></tr>`).join('')}</tbody></table></div>`:''}${item.fullyCompleted?`<div class="aigc-report-actions"><div><strong>PaperKnow 鉴别报告</strong><p>含分段明细与指标解释，可预览打印或保存到云文件。</p></div><button class="btn secondary" type="button" data-aigc-report-preview>预览 / 保存 PDF</button><button class="btn primary" type="button" data-aigc-report-download>下载 HTML 报告</button></div>`:''}<p class="aigc-detection-result-foot">置信分表示服务对单个片段标签的把握程度，不表示其中有多少文字由 AI 生成。${esc(AIGC_NOTICE)}</p>`;});const downloadButton=$('[data-aigc-report-download]'),previewButton=$('[data-aigc-report-preview]');if(downloadButton)downloadButton.onclick=()=>void command(downloadReport);if(previewButton)previewButton.onclick=()=>void command(showReport);updateControls();}
 function renderForm(){const limits=aigcLimits(cap);container.innerHTML=`<div class="aigc-detection"><section class="aigc-detection-card"><header class="aigc-detection-head"><span>${icon('shield',25)}</span><div><h2>AI 文本鉴别</h2><p>先了解表达倾向，再结合原稿和真实研究逐段核对。</p></div></header><div class="aigc-detection-import"><h3>准备需要鉴别的正文</h3><label>${icon('upload',15)} 导入文档<input type="file" accept=".txt,.docx,.pdf" data-aigc-file aria-label="导入待鉴别文档"></label></div><label class="sr-only" for="aigc-detection-text">待鉴别正文</label><textarea id="aigc-detection-text" data-aigc-text rows="10" placeholder="粘贴论文或文章正文。不会修改原文，也不会自动提交鉴别。"></textarea><div class="aigc-detection-input-meta"><span data-aigc-counter></span><span data-aigc-parts></span></div>${cap.bundleUsageSupported?'<p class="section-hint" data-detection-bundle-note>本次不扣积分；如已购套餐包含对应检测次数，将记录一次套餐使用，失败或取消会释放预占次数。</p>':''}<label class="aigc-detection-consent"><input type="checkbox" data-aigc-consent><span>我有权处理这些文本，同意将本次正文提交云端 AI 文本鉴别服务；已了解结果仅供参考，不代表学校论文 AI 率或原创性结论。</span></label><div class="aigc-detection-actions"><button class="btn primary" type="button" data-aigc-start>${icon('spark',16)} 开始鉴别</button><button class="btn secondary" type="button" data-aigc-refresh hidden>读取任务状态</button><button class="btn secondary" type="button" data-aigc-retry hidden>重试读取原提交</button></div><p class="aigc-detection-status" data-aigc-status role="status" aria-live="polite">确认授权后才会发送正文，结果只在当前账户内查看。</p><section class="aigc-detection-result" data-aigc-result hidden aria-label="AI 文本分段鉴别结果"></section></section><aside class="aigc-detection-card aigc-detection-side"><h3>先确认，再开始</h3><p>完整保留你的原稿，鉴别与表达修改分开进行。</p><dl><div><dt>本次费用</dt><dd>${cap.pointsCharged===false?'试用免费 · 不扣积分':'以提交前服务说明为准'}</dd></div><div><dt>单次正文</dt><dd>最多 ${limits.maxCharacters.toLocaleString('en-US')} 字符</dd></div><div><dt>每日次数</dt><dd>每账户 ${limits.userDailyLimit} 次</dd></div><div><dt>每日字符</dt><dd>最多 ${limits.userDailyCharacters.toLocaleString('en-US')} 字符</dd></div></dl><div class="aigc-detection-boundary"><h3>如何理解结果</h3><p>按片段展示「偏 AI 表达」「偏人工表达」或「暂不能明确判定」，不以平均置信分推算全篇比例。</p><p>${esc(AIGC_NOTICE)}</p><p>TXT / DOCX 在本地提取；PDF 需另行确认云解析，提取后还需确认本次鉴别授权。</p></div><section class="aigc-detection-recent" data-aigc-recent></section></aside></div>`;$('[data-aigc-text]').oninput=()=>{$('[data-aigc-consent]').checked=false;countInput();};$('[data-aigc-consent]').onchange=updateControls;$('[data-aigc-start]').onclick=()=>void command(submit);$('[data-aigc-refresh]').onclick=()=>void command(()=>read(item.id));$('[data-aigc-retry]').onclick=()=>void command(retry);$('[data-aigc-file]').onchange=()=>void importFile();countInput();renderRecent();}
 async function checkOwner(){const me=await client.request('/auth/me');if(!me.user?.id)throw Object.assign(Error('login required'),{status:401});if(me.user.id!==ownerId){blocked=true;closePreview();item=null;intent=null;resultText='';$('[data-aigc-text]').value='';$('[data-aigc-consent]').checked=false;recent=[];renderResult();renderRecent();throw publicError('登录账户已变化，原账户结果已隐藏。请重新进入本功能。');}return me.user;}
 function reportContent(){try{return aigcReportHtml(item,{text:resultText});}catch{throw publicError('报告内容暂不能完整核对，请先读取任务状态后再导出。');}}
 async function downloadReport(){
  await checkOwner();
  const reportItem=item,expectedOwner=ownerId,content=reportContent();
  const guardedFetch=async(path,options)=>{
   if(!current()||blocked||ownerId!==expectedOwner)throw publicError('账户或页面已变化，已停止报告导出。');
   if(path==='/api/auth/me'){await checkOwner();return new Response(JSON.stringify({user:{id:expectedOwner}}),{status:200,headers:{'Content-Type':'application/json'}});}
   const response=await (fetchImpl||globalThis.fetch)(path,options);
   if(/^\/api\/artifacts\/[^/]+\/download\?/.test(path)&&response.ok){
    // The session can change while the response body is still arriving.
    // Finish reading first, then revalidate the original owner before the
    // export helper is allowed to create a downloadable browser URL.
    const bytes=await response.blob();await checkOwner();
    if(!current()||blocked||ownerId!==expectedOwner)throw publicError('账户或页面已变化，已停止报告导出。');
    return new Response(bytes,{status:response.status,headers:response.headers});
   }
   return response;
  };
  let exported;try{exported=await exportFile({name:`PaperKnow-AIGC鉴别报告-${reportItem.id}.html`,content,type:'text/html;charset=utf-8',sourceType:'detection',sourceId:reportItem.id},{fetchImpl:guardedFetch,documentObject:doc});}catch(error){if(error.publicMessage||[401,403,409].includes(error.status))throw error;throw publicError('报告文件未能确认保存或下载，请在“文件管理”核对后重试；当前鉴别结果仍保留。');}
  await checkOwner();status(exported.message||'已保存报告，可在“文件管理”查看。');
 }
 async function showReport(){
  await checkOwner();const content=reportContent();closePreview();
  const dialog=doc.createElement('dialog');preview=dialog;dialog.className='aigc-report-preview';dialog.setAttribute('aria-label','PaperKnow AI 文本鉴别报告预览');
  dialog.innerHTML='<header><div><strong>PaperKnow 鉴别报告</strong><p>点击打印，在系统打印窗口中选择“另存为 PDF”。</p></div><button type="button" class="btn secondary" data-aigc-preview-download>下载 HTML</button><button type="button" class="btn primary" data-aigc-preview-print>打印 / 保存 PDF</button><button type="button" class="btn secondary" data-aigc-preview-close aria-label="关闭报告预览">关闭</button></header><iframe title="PaperKnow AI 文本鉴别报告" sandbox="allow-same-origin allow-modals" referrerpolicy="no-referrer"></iframe>';
  const frame=dialog.querySelector('iframe');frame.srcdoc=content;
  dialog.querySelector('[data-aigc-preview-close]').onclick=closePreview;
  dialog.querySelector('[data-aigc-preview-download]').onclick=()=>void command(downloadReport);
  dialog.querySelector('[data-aigc-preview-print]').onclick=()=>void command(async()=>{await checkOwner();if(preview!==dialog||!dialog.isConnected)return;try{frame.contentWindow.focus();frame.contentWindow.print();status('已请求系统打印，请选择“另存为 PDF”；PDF 保存在你选择的位置。');}catch{throw publicError('打印窗口未能打开，请下载 HTML 报告后使用浏览器打印。');}});
  dialog.addEventListener('cancel',event=>{event.preventDefault();closePreview();});dialog.addEventListener('close',closePreview,{once:true});
  doc.body.append(dialog);if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');
 }
 async function command(fn){if(busy||!current()||blocked)return;busy=true;updateControls();try{await fn();}catch(error){if(current()&&error.name!=='AbortError'){if(error.status===401){blocked=true;closePreview();item=null;intent=null;resultText='';recent=[];renderResult();renderRecent();$('[data-aigc-text]').value='';$('[data-aigc-auth]').hidden=false;}status(aigcPublicError(error),true);}}finally{if(current()){busy=false;updateControls();}}}
 function accept(value){const checked=normalizeAigcResult(value);if(item&&checked.id!==item.id&&intent===null)resultText='';closePreview();item=checked;intent=null;recent=recent.map(row=>row.id===checked.id?{...row,status:checked.status,characters:checked.characters}:row);persist();renderResult();renderRecent();schedule();}
 function schedule(){stop();if(current()&&item?.status==='running')timer=win.setTimeout(()=>void command(()=>read(item.id)),pollInterval);}
 async function recentItems(){const data=await client.request('/aigc-detections');recent=(data.items||[]).filter(row=>/^[-\w]{1,100}$/.test(String(row.id||''))&&['running','completed','failed'].includes(row.status)).map(row=>({id:row.id,status:row.status,characters:Number.isInteger(row.characters)&&row.characters>=0?row.characters:0}));renderRecent();}
 async function read(id){stop();await checkOwner();const result=await client.request('/aigc-detections/'+encodeURIComponent(id));await checkOwner();accept(result);status(result.status==='running'?'任务正在处理中，已自动保存到当前账户。':'已读取本次任务。请逐段核对表达倾向与置信分。');}
 async function retry(){if(!intent)return;await checkOwner();let response;try{response=await client.request('/aigc-detections',{text:intent.text,consent:true,expectedUserId:ownerId,idempotencyKey:intent.key});}catch(error){if(!item&&[400,413,422].includes(error.status)){intent=null;$('[data-aigc-consent]').checked=false;}throw error;}await checkOwner();resultText=intent.text;accept(response);status('已读取原提交，不会因重复点击新建相同任务。');await recentItems();}
 async function submit(){if(!cap.ready)throw publicError('AI 文本鉴别暂未开放，请稍后再试。');if(!$('[data-aigc-consent]').checked)throw publicError('请先确认正文处理授权与鉴别范围。');let input;try{input=validateAigcText($('[data-aigc-text]').value,cap);}catch(error){throw publicError(error.message);}await checkOwner();intent={text:input.text,key:uuid()};item=null;resultText='';renderResult();status(`本次提交 ${input.characters.toLocaleString('en-US')} 字符，预计 ${input.partCount} 个片段，正在创建任务…`);await retry();}
 async function importFile(){if(busy||blocked||importing||intent||item?.status==='running')return;const file=$('[data-aigc-file]').files?.[0];if(!file)return;if(file.size>50*1024*1024||!(/\.(txt|docx|pdf)$/i.test(file.name)))return status('请选择不超过 50MB 的 TXT、DOCX 或 PDF 文档；PDF 云解析还受 20MB / 100 页限制。',true);importing=true;updateControls();status('正在提取原文，尚未提交文本鉴别…');try{const extracted=await importDocument(file,$('[data-aigc-status]'));if(!current())return;try{validateAigcText(extracted.text,cap);}catch(error){throw publicError(error.message);}if($('[data-aigc-text]').value.trim()&&!win.confirm('文档提取已完成，是否替换当前待鉴别正文？')){status('已保留当前正文。');return;}$('[data-aigc-text]').value=extracted.text;$('[data-aigc-consent]').checked=false;countInput();status(`已提取 ${Array.from(extracted.text).length.toLocaleString('en-US')} 字符，请核对正文并确认本次鉴别。`);}catch(error){if(current()&&error.name!=='AbortError')status(error.publicMessage||'原文提取未完成，请检查文件或改用粘贴正文。',true);}finally{if(current()){importing=false;updateControls();}}}
 const ready=(async()=>{container.innerHTML='<p role="status">正在确认 AI 文本鉴别服务与账户…</p>';try{const [me,capabilities]=await Promise.all([client.request('/auth/me'),client.request('/capabilities')]);if(!current())return;cap=capabilities.aigcDetection||{};ownerId=me.user?.id||null;if(!ownerId||!cap.ready){container.innerHTML=`<section class="aigc-detection-card"><h2>${ownerId?'AI 文本鉴别暂未开放':'登录后使用 AI 文本鉴别'}</h2><p>${ownerId?'服务当前不可用，请稍后再试。表达优化与原稿编辑仍可使用。':'鉴别结果仅在当前账户内保存，表达修改功能仍可继续使用。'}</p>${!ownerId?`<a class="btn primary" href="/auth.html?mode=login&next=${encodeURIComponent('/workspace.html'+win.location.hash)}">登录账户 →</a>`:''}<p>${esc(AIGC_NOTICE)}</p></section>`;return;}if(cap.pointsCharged!==false){container.innerHTML='<section class="aigc-detection-card"><h2>服务费用待确认</h2><p>当前费用信息不完整，请稍后再试；不会自动提交鉴别。</p></section>';return;}renderForm();const auth=doc.createElement('p');auth.dataset.aigcAuth='';auth.hidden=true;auth.innerHTML=`<a class="btn primary" href="/auth.html?mode=login&next=${encodeURIComponent('/workspace.html'+win.location.hash)}">重新登录</a>`;$('[data-aigc-status]').after(auth);await recentItems();let stored;try{stored=JSON.parse(win.localStorage.getItem('paperknow-aigc-last:'+ownerId)||'null');}catch{}const requestedId=new URLSearchParams(win.location.hash.split('?')[1]||'').get('report'),id=/^[-A-Za-z0-9_]{1,100}$/.test(requestedId||'')?requestedId:recent.find(row=>row.id===stored?.itemId)?.id||recent[0]?.id;if(id)await command(()=>read(id));}catch(error){if(current()&&error.name!=='AbortError'){if($('[data-aigc-status]'))status(aigcPublicError(error),true);else container.innerHTML=`<section class="aigc-detection-card"><h2>暂时无法读取服务</h2><p role="alert">${esc(aigcPublicError(error))}</p></section>`;}}})();
 return {ready,dispose,refresh:()=>command(()=>item?read(item.id):recentItems())};
}
